@values jsEval
const slots = $slots;
const activated = new Set();
const deactivated = new Set();
for (const [from, to] of slots.rules) {
  activated.add(from);
  deactivated.add(to);
}
let changed = true;
while (changed) {
  changed = false;
  for (const rule of slots.rules) {
    if (activated.has(rule.from) && !activated.has(rule.to)) {
      activated.add(rule.to);
      changed = true;
    }
  }
}
const values = { B: activated.size, D: deactivated.size, E: slots.candidateObserved === "A" ? activated.size - 1 : deactivated.size };
probe(values.B + values.D + values.E === slots.candidateObserved.length, "the observed case must determine the values of B, D, and E");
probe(values.B >= 0 && values.D >= 0 && values.E >= 0, "the answers must be whole numbers of activated indicators");
probe(values.B + values.D + values.E < slots.candidate.length, "the derived values must not invent new indicators");
return { values, changed };

@answer jsEval
const prefixes = {
  A: "The rule is about A",
  B: "Rule 1: A and B are active",
  C: "Rule 2: A and C are inactive",
  D: "Rule 3: D and E are active",
  E: "Rule 4: E and A are active"
};
const main = prefixes[$slots.candidate] + "; Rule " + ($values.changed ? "is not necessary" : "is necessary") + ".";
return $values.values.B + " " + $values.values.D + " " + $values.values.E + ": " + main;

