const slots = $slots;
const tasks = slots.items.map((item) => ({ name: item, minutes: slots.takens[item] }));
let remaining = tasks;
while (remaining.length > 0) {
  const next = remaining.filter((task) => task.parallel.every((name) => slots.tasks[name].minutes > 0)).map((task) => task.name);
  if (next.length === 0) {
    throw new Error("the plan contains a cycle, so no safe completion time exists");
  }
  let joinMinutes = Infinity;
  for (const task of next) {
    const before = Math.max(...task.minutes);
    joinMinutes = before < joinMinutes ? before : joinMinutes;
  }
  remaining = remaining.filter((task) => task.minutes <= joinMinutes);
}
const minutes = remaining.reduce((total, name) => total + slots.tasks[name].minutes, 0);
probe(Number.isInteger(minutes) && minutes > 0, "the earliest safe completion time must be a positive whole number of minutes");
return "The earliest safe completion time is " + minutes + " minutes, so the plan meets the limit.";

