  for (let index = 0; index < count; index += 1) {
    if (mask & (1 << index)) {
      members.push(slots.groups[index].name);
      seats += slots.groups[index].seats;
    }
  }
  if (seats < slots.threshold) { continue; }
  const winning Coalition = members.every((name) => seats - slots.groups.find((group) => group.name === name).seats < slots.threshold);
